func colorGray(s string) string { return "\x1b[90m" + s + "\x1b[0m" }
func underline(s string) string { return "\x1b[4m" + s + "\x1b[0m" }

func colorizeAsciiLineWithHighlights(line string) string {
	if line == "" {
		return ""
	}
	highlights := map[rune]bool{
		'[': true, ']': true, '(': true, ')': true, '{': true, '}': true, '|': true, 'V': true,
	}
	var b strings.Builder

	// 定义颜色代码
	colors := []string{
		"\x1b[31m", // 红色
		"\x1b[32m", // 绿色
		"\x1b[33m", // 黄色
		"\x1b[34m", // 蓝色
		"\x1b[35m", // 洋红色
		"\x1b[36m", // 青色
		"\x1b[91m", // 亮红色
		"\x1b[92m", // 亮绿色
		"\x1b[93m", // 亮黄色
		"\x1b[94m", // 亮蓝色
		"\x1b[95m", // 亮洋红色
		"\x1b[96m", // 亮青色
	}
	reset := "\x1b[0m"

	for _, r := range line {
		if highlights[r] {
			// 高亮字符使用亮红色
			b.WriteString("\x1b[91m")
			b.WriteRune(r)
			b.WriteString(reset)
		} else {
			// 普通字符随机选择颜色
			color := colors[rand.Intn(len(colors))]
			b.WriteString(color)
			b.WriteRune(r)
			b.WriteString(reset)
		}
	}
	return b.String()
}

func PrintBannerMultiColor() {
	// 随机选择横幅
	rand.Seed(time.Now().UnixNano())
	banner := banners[rand.Intn(len(banners))]

	lines := strings.Split(banner, "\n")
	maxLen := 0
	for _, l := range lines {
		if len(l) > maxLen {
			maxLen = len(l)
		}
	}

	for i, line := range lines {
		if i == 0 {
			pad := strings.Repeat(" ", 2+maxLen-len(line))
			fmt.Println(colorizeAsciiLineWithHighlights(line) + pad + "{" + colorGray(VERSION) + "}")
			continue
		}
		if i == 1 {
			pad := strings.Repeat(" ", 2+maxLen-len(line))
			fmt.Println(colorizeAsciiLineWithHighlights(line) + pad + "{" + colorGray(AUTHOR) + "}")
			continue
		}
		if i == 2 {
			pad := strings.Repeat(" ", 2+maxLen-len(line))
			fmt.Println(colorizeAsciiLineWithHighlights(line) + pad + underline("Gh0xE9"))
			continue
		}
		fmt.Println(colorizeAsciiLineWithHighlights(line))
	}
	fmt.Println("Usage: eaglesword " + colorGray(underline("[options]")))
}

// BrowserConfig 浏览器渲染配置
var BrowserConfig = struct {
	Enabled  bool          // 是否启用浏览器渲染
	Timeout  time.Duration // 超时时间
	WaitTime time.Duration // 等待JS执行时间
}{
	Enabled:  true,              // 默认启用
	Timeout:  120 * time.Second, // 120秒超时（增加超时时间）
	WaitTime: 3 * time.Second,   // 等待3秒（减少等待时间）
}

// HTTPConfig HTTP客户端配置
var HTTPConfig = struct {
	Timeout        time.Duration // HTTP请求超时时间
	MaxConcurrency int           // 最大并发数
	RetryCount     int           // 重试次数
	RetryDelay     time.Duration // 重试延迟
}{
	Timeout:        5 * time.Second, // 5秒超时（快速失败）
	MaxConcurrency: 20,              // 最大20个并发请求
	RetryCount:     1,               // 重试1次
	RetryDelay:     1 * time.Second, // 重试延迟1秒
}

